{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, the closest analogue, has very low absolute oral bioavailability (mean 4.9%) in patients, but its low F is driven by a ketone moiety and lacks the basic amine side chain present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, a dimethoxy-substituted basic CNS drug, has complete oral bioavailability (100%) in humans, supporting high F for the query's similar dimethoxy/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a dimethoxy-tetrahydroisoquinoline derivative, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Almorexant, a large lipophilic CNS drug, has absolute oral bioavailability of about 11%, providing some low-F evidence, but its structural similarity to the query is lower.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C50"],
      "claim": "Verapamil, which shares dimethoxyphenyl and tertiary amine features, has absolute oral bioavailability of 22% in normal subjects, at or above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Urapidil, a dimethoxyphenyl piperazine, has absolute oral bioavailability of 78%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a dimethoxyisoquinoline alkaloid, has absolute oral bioavailability of 30% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Gallopamil, a verapamil analog with dimethoxyphenyl groups, has bioavailability of 96.3% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on multiple direct human absolute bioavailability measurements in structurally related dimethoxy-substituted basic CNS drugs (donepezil, valbenazine, urapidil, noscapine, gallopamil), outweighing low-F analogues (tetrabenazine, almorexant) that are less transferable due to different metabolic/structural features.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "No experimental data on solubility, permeability, or first-pass metabolism for the query.",
    "Tetrabenazine's low F may not transfer because the query lacks the ketone and has a basic amine side chain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

